-- Schemas for the procure-to-pay artefact kinds (docs/examples/workflows/p2p). Source of truth: packages/schemas/*.json.
-- Regenerate with: node packages/schemas/gen-p2p-migration.mjs
insert into baton.artifact_schemas (kind, version, schema) values ('purchase_order', 'v1', '{"$schema":"http://json-schema.org/draft-07/schema#","$id":"https://clane.sh/baton/schemas/purchase_order/v1","title":"purchase_order","description":"A purchase order raised from a requisition: what is bought, from whom, for how much, and whether policy requires a human approval.","type":"object","required":["po_number","requisition","vendor","currency","lines","total","cost_center","policy_check"],"properties":{"po_number":{"type":"string","pattern":"^PO-[0-9]{4}-[0-9]{3,}$"},"requisition":{"type":"string","description":"The requisition number this PO fulfils, e.g. PR-2026-104."},"requester":{"type":"string"},"vendor":{"type":"object","required":["id","name"],"properties":{"id":{"type":"string"},"name":{"type":"string"},"approved":{"type":"boolean"},"email":{"type":"string"}}},"currency":{"type":"string","enum":["EUR","USD","GBP"]},"lines":{"type":"array","minItems":1,"items":{"type":"object","required":["line","item","quantity","unit_price"],"properties":{"line":{"type":"integer","minimum":1},"sku":{"type":"string"},"item":{"type":"string","minLength":1},"quantity":{"type":"number","exclusiveMinimum":0},"unit":{"type":"string"},"unit_price":{"type":"number","minimum":0},"line_total":{"type":"number"}}}},"total":{"type":"number","minimum":0},"cost_center":{"type":"string"},"delivery_address":{"type":"string"},"needed_by":{"type":"string"},"policy_check":{"type":"object","required":["approval_required","notes"],"properties":{"approval_required":{"type":"boolean"},"approver_level":{"type":"string","enum":["none","manager","director","cfo"]},"vendor_approved":{"type":"boolean"},"within_budget":{"type":"boolean"},"notes":{"type":"string"}}}},"additionalProperties":true}'::jsonb)
  on conflict (kind, version) do update set schema = excluded.schema;
insert into baton.artifact_schemas (kind, version, schema) values ('delivery_note', 'v1', '{"$schema":"http://json-schema.org/draft-07/schema#","$id":"https://clane.sh/baton/schemas/delivery_note/v1","title":"delivery_note","description":"The supplier delivery note for a purchase order: what was shipped, when, and where the document lives.","type":"object","required":["delivery_note_number","po_number","vendor","shipped_at","lines"],"properties":{"delivery_note_number":{"type":"string"},"po_number":{"type":"string"},"vendor":{"type":"string"},"shipped_at":{"type":"string"},"carrier":{"type":"string"},"tracking":{"type":"string"},"lines":{"type":"array","minItems":1,"items":{"type":"object","required":["line","item","quantity_shipped"],"properties":{"line":{"type":"integer"},"sku":{"type":"string"},"item":{"type":"string"},"quantity_shipped":{"type":"number","minimum":0}}}},"document_path":{"type":"string","description":"Where the PDF was filed, relative to the shared inbox."},"email_path":{"type":"string"}},"additionalProperties":true}'::jsonb)
  on conflict (kind, version) do update set schema = excluded.schema;
insert into baton.artifact_schemas (kind, version, schema) values ('invoice', 'v1', '{"$schema":"http://json-schema.org/draft-07/schema#","$id":"https://clane.sh/baton/schemas/invoice/v1","title":"invoice","description":"A supplier invoice as received: header, lines and totals, plus where the document was filed.","type":"object","required":["invoice_number","po_number","vendor","issued_at","due_at","currency","lines","total"],"properties":{"invoice_number":{"type":"string"},"po_number":{"type":"string"},"vendor":{"type":"string"},"issued_at":{"type":"string"},"due_at":{"type":"string"},"currency":{"type":"string"},"lines":{"type":"array","minItems":1,"items":{"type":"object","required":["line","item","quantity","unit_price","line_total"],"properties":{"line":{"type":"integer"},"sku":{"type":"string"},"item":{"type":"string"},"quantity":{"type":"number"},"unit_price":{"type":"number"},"line_total":{"type":"number"}}}},"subtotal":{"type":"number"},"tax":{"type":"number"},"total":{"type":"number"},"bank":{"type":"object","properties":{"iban":{"type":"string"},"bic":{"type":"string"}}},"document_path":{"type":"string"},"email_path":{"type":"string"}},"additionalProperties":true}'::jsonb)
  on conflict (kind, version) do update set schema = excluded.schema;
insert into baton.artifact_schemas (kind, version, schema) values ('goods_receipt', 'v1', '{"$schema":"http://json-schema.org/draft-07/schema#","$id":"https://clane.sh/baton/schemas/goods_receipt/v1","title":"goods_receipt","description":"What the warehouse actually received against a purchase order, line by line, with any discrepancy against the delivery note or the order.","type":"object","required":["grn_number","po_number","received_at","received_by","lines","complete"],"properties":{"grn_number":{"type":"string","pattern":"^GRN-"},"po_number":{"type":"string"},"delivery_note_number":{"type":"string"},"received_at":{"type":"string"},"received_by":{"type":"string"},"lines":{"type":"array","minItems":1,"items":{"type":"object","required":["line","item","quantity_ordered","quantity_received","condition"],"properties":{"line":{"type":"integer"},"sku":{"type":"string"},"item":{"type":"string"},"quantity_ordered":{"type":"number"},"quantity_received":{"type":"number","minimum":0},"condition":{"type":"string","enum":["good","damaged","missing"]},"note":{"type":"string"}}}},"complete":{"type":"boolean","description":"True when every line was received in full and in good condition."},"discrepancies":{"type":"array","items":{"type":"string"}}},"additionalProperties":true}'::jsonb)
  on conflict (kind, version) do update set schema = excluded.schema;
insert into baton.artifact_schemas (kind, version, schema) values ('invoice_match', 'v1', '{"$schema":"http://json-schema.org/draft-07/schema#","$id":"https://clane.sh/baton/schemas/invoice_match/v1","title":"invoice_match","description":"The three-way match of purchase order, goods receipt and invoice. status decides whether the invoice may be paid.","type":"object","required":["invoice_number","po_number","grn_number","status","lines","summary"],"properties":{"invoice_number":{"type":"string"},"po_number":{"type":"string"},"grn_number":{"type":"string"},"status":{"type":"string","enum":["matched","mismatched"]},"tolerance":{"type":"object","properties":{"price_pct":{"type":"number"},"quantity":{"type":"number"}}},"lines":{"type":"array","minItems":1,"items":{"type":"object","required":["line","ordered_qty","received_qty","invoiced_qty","po_unit_price","invoice_unit_price","ok"],"properties":{"line":{"type":"integer"},"item":{"type":"string"},"ordered_qty":{"type":"number"},"received_qty":{"type":"number"},"invoiced_qty":{"type":"number"},"po_unit_price":{"type":"number"},"invoice_unit_price":{"type":"number"},"ok":{"type":"boolean"},"variance":{"type":"string"}}}},"amount_payable":{"type":"number","minimum":0},"variances":{"type":"array","items":{"type":"string"}},"summary":{"type":"string","minLength":1}},"additionalProperties":true}'::jsonb)
  on conflict (kind, version) do update set schema = excluded.schema;
insert into baton.artifact_schemas (kind, version, schema) values ('payment', 'v1', '{"$schema":"http://json-schema.org/draft-07/schema#","$id":"https://clane.sh/baton/schemas/payment/v1","title":"payment","description":"A payment instruction accepted by the bank gateway for a matched invoice.","type":"object","required":["payment_ref","invoice_number","po_number","amount","currency","status","scheduled_for"],"properties":{"payment_ref":{"type":"string"},"invoice_number":{"type":"string"},"po_number":{"type":"string"},"amount":{"type":"number","exclusiveMinimum":0},"currency":{"type":"string"},"beneficiary":{"type":"object","properties":{"name":{"type":"string"},"iban":{"type":"string"}}},"status":{"type":"string","enum":["scheduled","sent","rejected"]},"scheduled_for":{"type":"string"},"remittance_path":{"type":"string"},"vendor":{"type":"string"}},"additionalProperties":true}'::jsonb)
  on conflict (kind, version) do update set schema = excluded.schema;
